<script setup>
import { ref, computed, onMounted, onBeforeUnmount, nextTick, watch } from 'vue';
import { EditorContent, useEditor } from '@tiptap/vue-3';
import { LayoutDashboard, BookOpen, Image, MessageSquare, ListChecks, Database, History, Plus, Search, ArrowUpRight, ChevronRight, Check, X, Save, Table, Heading2, Bold, Italic, Info, ChevronDown, RefreshCw, Archive, MoveRight, Upload, Undo2, FileText, Link } from '@lucide/vue';
import ContentLibrary from './ContentLibrary.vue';
import SiteSettings from './SiteSettings.vue';
import ReleaseReview from './ReleaseReview.vue';
import { extensions, setEditorAccess } from './editor.mjs';
import { findEditorTarget, validateImageFile } from './targets.mjs';
const nav = [{id:'dashboard',title:'Übersicht',icon:LayoutDashboard},{id:'guides',title:'Beiträge',icon:BookOpen},{id:'review',title:'Freigaben',icon:Check},{id:'site',title:'Website',icon:LayoutDashboard},{id:'users',title:'Benutzer & Rechte',icon:ListChecks},{id:'screenshots',title:'Medien',icon:Image},{id:'comments',title:'Kommentare',icon:MessageSquare},{id:'tasks',title:'Offene Aufgaben',icon:ListChecks},{id:'versions',title:'Versionen',icon:History}];
const page = ref('dashboard'), state = ref(null), loading = ref(true), busy = ref(false), error = ref(''), notice = ref(''), query = ref(''), category = ref(''), chosen = ref('guide:pets'), dirty = ref(false), sourceMode = ref(false), source = ref(''), title = ref(''), dialog = ref(null), form = ref({}), diff = ref(''), includeDone = ref(false);
const isLocal = ['127.0.0.1','localhost'].includes(location.hostname);
const apiOrigin = (import.meta.env.VITE_STUDIO_API_ORIGIN || '').replace(/\/$/,'');
const session = ref('');
const dragTarget=ref(null),editOpen=ref(false),releaseTarget=ref(null),siteDirty=ref(false),users=ref([]);
const allowed=p=>!!state.value&&(!state.value.permissions||state.value.permissions.includes(p));
const visibleNav=computed(()=>nav.filter(n=>n.id!=='users'||allowed('user.manage')).filter(n=>n.id!=='site'||state.value?.site));
function publicationLabel(g){const p=state.value?.publication;if(!p)return 'Online-Stand nicht verfügbar';if(!p.files[g.path])return 'Noch nicht veröffentlicht';return [p.files[g.path],p.receipt?.[g.path]].includes(g.blobSha)?'Online · aktueller Stand':'Online · Änderungen im Entwurf';}
async function review(target){if(dirty.value||siteDirty.value){error.value='Bitte zuerst die Änderungen speichern.';return;}releaseTarget.value=target;page.value='release';nextTick(()=>window.scrollTo({top:0,behavior:'instant'}));}
async function publish(){busy.value=true;error.value='';try{const result=await api('publish',{target:releaseTarget.value,expectedHead:state.value.head,expectedPublicHead:state.value.publication.head});await load();notice.value='Veröffentlichung übernommen. GitHub baut die Website neu auf. Den Build-Status findest du unter Versionen.';page.value=releaseTarget.value==='site'?'site':'guides';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function uploadSite({file,alt}){try{validateImageFile(file);const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(new Error('Bild konnte nicht gelesen werden.'));r.readAsDataURL(file);});await command({op:'site.image',base64,alt});}catch(e){error.value=e.message;}}
async function loadUsers(){try{users.value=(await api('users')).users;}catch(e){error.value=e.message;}}
async function saveUser(){busy.value=true;error.value='';try{await api('users',{subject:form.value.subject,expectedRevision:form.value.revision||0,grant:{...(users.value.find(u=>u.subject===form.value.subject)?.grant_json||{guideIds:null,overrides:{}}),role:form.value.role,disabled:form.value.disabled===true}});closeDialog();await loadUsers();notice.value='Benutzerrechte gespeichert.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
let insertionSelection=null;
const imageSource = src => !apiOrigin || src==='/images/voidborn-rift.png' || !src.startsWith('/images/') ? src : `https://raw.githubusercontent.com/voidborn-legion/voidborn-legion.github.io/${state.value?.head}/docs/public${src}`;
const selected = computed(()=>state.value?.guides.find(g=>g.id===chosen.value));
const bundle = computed(()=>state.value?.snapshot.bundles.find(b=>b.guideId===chosen.value));
const allItems = field => state.value?.snapshot.bundles.flatMap(b=>b[field].map(i=>({...i,guideId:b.guideId})))||[];
const screenshots = computed(()=>allItems('placeholders').filter(i=>(includeDone.value||['missing','needs-review'].includes(i.status))&&matches(i.title+' '+i.description)));
const comments = computed(()=>allItems('comments').filter(i=>(includeDone.value||i.status!=='done')&&matches(i.body)));
const tasks = computed(()=>allItems('tasks').filter(i=>(includeDone.value||i.status!=='done')&&matches(i.title)));
const guideList = computed(()=>state.value?.guides.filter(g=>matches(g.title)&&(!category.value||g.categoryId===category.value))||[]);
const allAssets = computed(()=>state.value?.snapshot.bundles.flatMap(b=>b.assets)||[]);
const label = s=>({missing:'Bild fehlt','needs-review':'Bitte prüfen',ready:'Vorhanden',archived:'Archiviert',open:'Offen','in-progress':'In Bearbeitung',done:'Erledigt',draft:'Entwurf',published:'Veröffentlicht',pending:'Noch prüfen',orientation:'Guide folgt',help:'Website-Hilfe',verified:'Geprüft',unverified:'Unbestätigt',conflicting:'Widersprüchlich'}[s]||s);
const guideTitle = id=>state.value?.guides.find(g=>g.id===id)?.title||id;
const matches = text=>!query.value||text.toLowerCase().includes(query.value.toLowerCase());
const editor = useEditor({ extensions: extensions(imageSource), content: '', onUpdate:({transaction})=>{if(transaction.docChanged)dirty.value=true;}, editorProps:{attributes:{'aria-label':'Guide-Inhalt',class:'guide-document'}} });
async function api(path, body) {
  const response=await fetch(apiOrigin+'/api/'+path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(session.value?{Authorization:'Bearer '+session.value}:{})},body:body?JSON.stringify(body):undefined});
  const result=await response.json(); if(!response.ok){const failure=new Error(result.error||'Die Verbindung ist fehlgeschlagen.');failure.status=response.status;throw failure;} return result;
}
async function load(){loading.value=true;error.value='';try{state.value=await api('state');}catch(e){if(e.status===401){session.value='';state.value=null;}else if(e.message!=='NOT_INITIALIZED')error.value=e.message==='Failed to fetch'?'Der Anmeldedienst ist gerade nicht erreichbar. Bitte erneut versuchen.':e.message;}finally{loading.value=false;}}
async function signOut(){try{await api('logout',{});}catch{}finally{session.value='';state.value=null;notice.value='Du bist abgemeldet.';}}
async function init(){busy.value=true;error.value='';try{state.value=await api('init',{});notice.value='Der Pets-Entwurf ist als eigener lokaler Arbeitsstand geöffnet.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function signIn(){
 if(!apiOrigin){error.value='Der Anmeldedienst ist noch nicht eingerichtet.';return;}
 const popup=window.open('about:blank','voidborn-login','width=660,height=740');if(!popup){error.value='Bitte das Anmeldefenster im Browser erlauben.';return;}
 const verifier=Array.from(crypto.getRandomValues(new Uint8Array(32)),b=>b.toString(16).padStart(2,'0')).join('');
 const bytes=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)));
 const challenge=btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'');
 const receive=async event=>{
   if(event.origin!==new URL(apiOrigin).origin||event.source!==popup||event.data?.type!=='voidborn-login')return;
   window.removeEventListener('message',receive);
   try{const response=await fetch(apiOrigin+'/auth/exchange',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ticket:event.data.ticket,verifier})});const data=await response.json();if(!response.ok)throw new Error(data.error);session.value=data.session;await load();}catch(e){error.value=e.message;}
 };
 window.addEventListener('message',receive);setTimeout(()=>window.removeEventListener('message',receive),600000);
 popup.location=apiOrigin+'/auth/start?challenge='+encodeURIComponent(challenge);
}
async function command(data){busy.value=true;error.value='';try{const saved=await api('command',{...data,expectedHead:state.value.head});state.value=saved.commitSha?await api('state'):saved;notice.value='Als Entwurf gespeichert. Nichts veröffentlicht.';return true;}catch(e){error.value=e.message;return false;}finally{busy.value=false;}}
function setPage(id){if(dirty.value||siteDirty.value){error.value='Dein Text ist noch nicht gespeichert. Speichere ihn zuerst oder wähle „Änderungen verwerfen“.';return;}error.value='';page.value=id;editOpen.value=false;if(id==='users')loadUsers();query.value='';diff.value='';location.hash=id;nextTick(()=>window.scrollTo({top:0,behavior:'instant'}));}
async function openGuide(id){if(siteDirty.value||(dirty.value&&id!==chosen.value)){error.value='Bitte zuerst den aktuellen Text speichern.';return;}chosen.value=id;editOpen.value=true;page.value='guides';await nextTick();resetEditor();window.scrollTo({top:0,behavior:'instant'});}
function resetEditor(){if(!selected.value||!editor.value)return;title.value=selected.value.title;source.value=selected.value.body;editor.value.commands.setContent(source.value,{contentType:'markdown',emitUpdate:false});dirty.value=false;}
function switchMode(){if(sourceMode.value){editor.value.commands.setContent(source.value,{contentType:'markdown',emitUpdate:false});}else{source.value=dirty.value?editor.value.getMarkdown():selected.value.body;}sourceMode.value=!sourceMode.value;}
async function saveGuide(){const body=sourceMode.value?source.value:(dirty.value?editor.value.getMarkdown():selected.value.body);if(await command({op:'guide.save',guideId:chosen.value,title:title.value,body})){dirty.value=false;resetEditor();}}
function selection(){const {from,to}=editor.value.state.selection;return editor.value.state.doc.textBetween(from,to,'\n').trim();}
let previousFocus=null;
function showDialog(type,extra={}){previousFocus=document.activeElement;error.value='';if(type==='screenshot')insertionSelection={from:editor.value.state.selection.from,to:editor.value.state.selection.to,guideId:chosen.value};nextTick(()=>document.querySelector('.dialog input:not([type=file]),.dialog textarea,.dialog select')?.focus());form.value={title:'',body:'',quote:page.value==='guides'&&!sourceMode.value?selection():'',description:'',kind:'info',role:'dps',classes:'',alt:'',caption:'',slug:'',categoryId:'',min:null,max:null,region:'Global/EU',patch:'',slot:1,board:'Cognia',mode:'pve',effect:'',unit:'percent',threshold:null,sourceId:'',...extra};dialog.value=type;}
function dropImage(event,item){event.preventDefault();dragTarget.value=null;if(busy.value)return;try{const files=[...event.dataTransfer.files];if(files.length!==1)throw new Error('Bitte genau ein Bild auf den gewünschten Platzhalter ziehen.');showDialog('upload',{id:item.id,alt:item.title,file:validateImageFile(files[0])});}catch(e){error.value=e.message;}}
async function reorderCategory(index,direction){const ids=state.value.snapshot.catalog.categories.map(c=>c.id);[ids[index],ids[index+direction]]=[ids[index+direction],ids[index]];await command({op:'category.reorder',ids});}
function closeDialog(){dialog.value=null;nextTick(()=>previousFocus?.focus());}
async function submitDialog(){
 let ok=false;const f=form.value;
 if(dialog.value==='box'){editor.value.chain().focus().insertContent({type:'academyBox',attrs:{kind:f.kind,title:f.title||'Gut zu wissen'},content:[{type:'paragraph',content:[{type:'text',text:f.body||'Deine Erklärung.'}]}]}).run();closeDialog();return;}
 if(dialog.value==='link'){if(!/^(https?:\/\/|\/|\.\/)/.test(f.body)){error.value='Bitte eine vollständige Webadresse oder einen internen Pfad eingeben.';return;}editor.value.chain().focus().setLink({href:f.body}).run();closeDialog();return;}
 if(dialog.value==='comment')ok=await command({op:'comment.add',guideId:chosen.value,quote:f.quote,body:f.body});
 if(dialog.value==='reply')ok=await command({op:'comment.reply',id:f.id,body:f.body});
 if(dialog.value==='task')ok=await command({op:'task.add',guideId:chosen.value,title:f.title,quote:f.quote});
 if(dialog.value==='screenshot'){
   if(!insertionSelection||insertionSelection.guideId!==chosen.value){error.value='Bitte die Stelle im Guide erneut anklicken.';return;}
   if(/[\r\n]/.test(f.title)||/^\s*:::/m.test(f.description)){error.value='Bitte einen kurzen Titel und eine Beschreibung ohne Box-Markierungen verwenden.';return;}
   const before=editor.value.getJSON(),wasDirty=dirty.value,id='screenshot:'+crypto.randomUUID();
   editor.value.chain().setTextSelection(insertionSelection.from).insertContent({type:'academyScreenshot',attrs:{id,title:f.title,description:f.description}}).run();
   ok=await command({op:'screenshot.insert',guideId:chosen.value,id,title:f.title,guideTitle:title.value,description:f.description,body:editor.value.getMarkdown()});
   if(ok){dirty.value=false;resetEditor();}else{editor.value.commands.setContent(before,{emitUpdate:false});dirty.value=wasDirty;}
 }
 if(dialog.value==='create')ok=await command({op:'guide.create',title:f.title,slug:f.slug,categoryId:f.categoryId});
 if(dialog.value==='reuse')ok=await command({op:'screenshot.reuse',id:f.id,assetId:f.assetId});
 if(dialog.value==='move')ok=await command({op:'guide.move',guideId:chosen.value,slug:f.slug});
 if(dialog.value==='upload'){
   if(!f.file){error.value='Bitte zuerst ein Bild auswählen.';return;}
   try{validateImageFile(f.file);const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(new Error('Das Bild konnte nicht gelesen werden. Bitte erneut auswählen.'));r.readAsDataURL(f.file);});ok=await command({op:'screenshot.upload',id:f.id,base64:data,alt:f.alt,caption:f.caption});}catch(e){error.value=e.message;}
 }
 if(dialog.value==='game'){
   const previous=state.value.snapshot.gameValues.find(v=>v.id===f.id); const ids=f.sourceId?[f.sourceId,...(previous?.verification.sourceIds||[]).filter(x=>x!==f.sourceId)]:[];
   const record={id:f.id||'value:'+crypto.randomUUID(),guideId:'guide:pets',board:f.board,slot:Number(f.slot),classIds:f.classes?f.classes.split(',').map(s=>s.trim()).filter(Boolean):(previous?.classIds||[]),role:f.role||previous?.role||'dps',mode:f.mode,effect:f.effect,unit:f.unit,min:f.min===''||f.min===null?null:Number(f.min),max:f.max===''||f.max===null?null:Number(f.max),alternativeEffectIds:previous?.alternativeEffectIds||[],recommendation:f.threshold===''||f.threshold===null?null:{value:Number(f.threshold),rationale:f.body||'Vorläufige Academy-Empfehlung',sourceIds:ids},verification:{status:'unverified',region:f.region,patch:f.patch||null,sourceIds:ids}};
   const records=state.value.snapshot.gameValues.filter(v=>v.id!==record.id);records.push(record);ok=await command({op:'game.save',records});
 }
 if(ok){closeDialog();if(page.value==='guides'&&!dirty.value)resetEditor();}
}
async function jump(item){if(dirty.value||siteDirty.value){error.value='Bitte zuerst den aktuellen Text speichern oder die Änderungen verwerfen.';return;}await openGuide(item.guideId);sourceMode.value=false;await nextTick();const asset=allAssets.value.find(a=>a.id===item.assetId);const target=findEditorTarget(editor.value.state.doc,{anchor:item.anchor,assetPath:asset?'/'+asset.path.slice('docs/public/'.length):null});if(!target){notice.value='Die Stelle fehlt oder kommt mehrfach vor. Bitte die Zuordnung prüfen.';return;}editor.value.chain().focus().setTextSelection({from:target.from,to:target.to}).run();await nextTick();let el=editor.value.view.nodeDOM(target.pos);if(el?.nodeType!==1)el=el?.parentElement;el?.scrollIntoView({block:'center',behavior:'instant'});el?.classList.add('studio-target');setTimeout(()=>el?.classList.remove('studio-target'),4500);}
async function compare(version){try{const result=await api(`diff?guide=${encodeURIComponent(chosen.value)}&before=${version}`);diff.value=result.diff||'Keine Textänderung gegenüber dem aktuellen Stand.';}catch(e){error.value=e.message;}}
async function loadVersions(){if(!apiOrigin||!selected.value)return;try{const result=await api('history?guide='+encodeURIComponent(chosen.value));selected.value.versions=result.versions;}catch(e){error.value=e.message;}}
function statusForAnchor(item){const g=state.value?.guides.find(g=>g.id===item.guideId);if(!g||!item.anchor)return '';const quote=item.anchor.quote;if(!g.body.includes(quote))return 'Textstelle verändert';if(g.blobSha!==item.anchor.baseBlobSha)return 'Zuordnung bitte prüfen';return 'Textstelle vorhanden';}
function trapDialog(event){if(!dialog.value)return;if(event.key==='Escape'){event.preventDefault();closeDialog();}if(event.key==='Tab'){const nodes=[...document.querySelectorAll('.dialog button:not([disabled]),.dialog input,.dialog textarea,.dialog select')];const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}
function unload(event){if(dirty.value||siteDirty.value){event.preventDefault();event.returnValue='';}}
onMounted(()=>{load();window.addEventListener('beforeunload',unload);window.addEventListener('keydown',trapDialog);});
onBeforeUnmount(()=>{window.removeEventListener('beforeunload',unload);window.removeEventListener('keydown',trapDialog);});
watch(()=>editor.value,()=>{setEditorAccess(editor.value,allowed('guide.edit'));if(selected.value)resetEditor();});
watch(()=>state.value?.permissions,()=>setEditorAccess(editor.value,allowed('guide.edit')));
watch(()=>selected.value?.id,()=>{if(!dirty.value)nextTick(resetEditor);});
watch(guideList,list=>{if(editOpen.value&&page.value==='guides'&&!dirty.value&&list.length&&!list.some(g=>g.id===chosen.value))openGuide(list[0].id);});
watch([page,chosen],()=>{if(page.value==='versions')loadVersions();});
</script>

<template>
 <div class="studio-shell">
  <aside class="sidebar" :inert="!!dialog">
   <a class="brand" href="#dashboard" @click.prevent="setPage('dashboard')"><svg class="crest" viewBox="0 0 36 40" aria-hidden="true"><path d="M2 3h9l8 23L27 3h7L19 39z" fill="currentColor"/></svg><span>VOIDBORN<small>Academy Studio</small></span></a>
   <nav v-if="state" aria-label="Studio-Navigation"><button v-for="n in visibleNav" :key="n.id" :class="{active:page===n.id}" @click="setPage(n.id)"><component :is="n.icon" :size="19"/><span>{{n.title}}</span><span v-if="state&&n.id==='screenshots'" class="nav-count">{{state.dashboard.missingScreenshots.length}}</span></button></nav>
   <div class="sidebar-bottom"><a href="https://voidborn-legion.github.io/" target="_blank" rel="noopener">Academy ansehen <ArrowUpRight :size="16"/></a><p><span class="status-dot"></span> {{state?.mode==='github'?'Mit GitHub verbunden':apiOrigin?'Nicht angemeldet':'Lokaler Arbeitsstand'}}</p><small>Speichern veröffentlicht nicht.</small></div>
  </aside>
  <main :inert="!!dialog">
   <header class="topbar"><span>Academy <ChevronRight :size="15"/> {{nav.find(n=>n.id===page)?.title}}</span><button v-if="state?.mode==='github'" class="quiet" :disabled="busy||dirty" @click="signOut">Abmelden</button><button v-if="state" class="quiet" :disabled="busy||dirty" @click="load"><RefreshCw :size="16"/> Neu laden</button></header>
   <div class="page-content">
    <div v-if="error" role="alert" class="alert error">{{error}}<button aria-label="Fehlermeldung schließen" @click="error=''"><X :size="17"/></button></div>
    <div v-if="notice" role="status" class="alert notice">{{notice}}<button aria-label="Hinweis schließen" @click="notice=''"><X :size="17"/></button></div>
    <div v-if="loading" class="empty"><RefreshCw :size="26"/><h1>Studio wird geladen …</h1></div>
    <section v-else-if="!state" class="welcome"><BookOpen :size="42"/><h1>Deine Academy.<br>Dein Arbeitsbereich.</h1><p>Guides bearbeiten, fehlende Bilder sammeln und Fragen direkt am Text klären. Speichern und Veröffentlichen sind getrennte Schritte.</p><button v-if="isLocal&&!apiOrigin" class="primary" :disabled="busy" @click="init">{{busy?'Entwurf wird geöffnet …':'Lokalen Pets-Entwurf öffnen'}} <ChevronRight :size="18"/></button><button v-else class="primary" :disabled="busy" @click="signIn">Mit GitHub anmelden <ArrowUpRight :size="18"/></button><p class="muted">{{isLocal&&!apiOrigin?'Lokaler Zugriff auf diesem Rechner. Es wird ein separater Entwurfsbranch angelegt; kein Push und keine Veröffentlichung.':apiOrigin?'Melde dich mit deinem GitHub-Konto an. Dein Konto braucht eine Academy-Freigabe. Inhalte im öffentlichen Repository bleiben öffentlich lesbar.':'Die GitHub-Anmeldung ist für diese Vorschau noch nicht eingerichtet.'}}</p></section>
    <template v-else>
     <section v-if="page==='dashboard'">
      <div class="page-heading"><div><h1>Alles im Blick.</h1><p>Hier geht es mit der Voidborn Academy weiter.</p></div><button v-if="allowed('guide.create')" class="primary" @click="showDialog('create')"><Plus :size="17"/> Guide erstellen</button></div>
      <div class="overview"><button @click="setPage('guides')"><strong>{{state.guides.length}}</strong> Guides <ChevronRight :size="16"/></button><button @click="setPage('screenshots')"><strong>{{state.dashboard.missingScreenshots.length}}</strong> fehlende Bilder <ChevronRight :size="16"/></button><button @click="setPage('comments')"><strong>{{state.dashboard.openComments.length}}</strong> {{state.dashboard.openComments.length===1?'offener Kommentar':'offene Kommentare'}} <ChevronRight :size="16"/></button><button @click="setPage('tasks')"><strong>{{state.dashboard.openTasks.length}}</strong> offene Aufgaben <ChevronRight :size="16"/></button></div>
      <div class="dashboard-work"><section><h2>Beiträge bearbeiten</h2><p>In der Beitragsliste siehst du getrennt, was online ist und woran noch gearbeitet wird.</p><button class="primary" @click="setPage('guides')">Beiträge öffnen <ChevronRight :size="17"/></button></section><section><h2>Zur Freigabe</h2><p>{{state.guides.filter(g=>g.frontmatter.reviewRequest&&publicationLabel(g)!=='Online · aktueller Stand').length}} Beiträge warten auf eine Entscheidung.</p><button class="secondary" @click="setPage('review')">Freigaben ansehen</button></section><section v-if="state.site"><h2>Website pflegen</h2><p>Startseite, Bild und Links in der Kopfleiste ändern.</p><button class="secondary" @click="setPage('site')">Website bearbeiten</button></section></div>
     </section>
     <section v-if="page==='guides'">
      <template v-if="!editOpen"><div class="page-heading"><div><h1>Beiträge</h1><p>Online-Fassung, Entwürfe und Freigaben getrennt im Blick.</p></div><button v-if="allowed('guide.create')" class="primary" @click="showDialog('create')"><Plus :size="17"/> Neuer Beitrag</button></div><ContentLibrary :state="state" @open="openGuide"/><details v-if="allowed('guide.organize')" class="category-order"><summary>Themen-Reihenfolge ändern</summary><div v-for="(c,index) in state.snapshot.catalog.categories" :key="c.id"><span>{{state.categories.find(x=>x.slug===c.slug)?.title||c.slug}}</span><button :disabled="index===0||busy" @click="reorderCategory(index,-1)">Nach oben</button><button :disabled="index===state.snapshot.catalog.categories.length-1||busy" @click="reorderCategory(index,1)">Nach unten</button></div></details></template>
      <button v-if="editOpen" class="quiet back-to-list" @click="setPage('guides')">← Alle Beiträge</button>
      <template v-if="selected&&editOpen"><div class="editor-heading"><input v-model="title" :readonly="!allowed('guide.edit')" class="title-input" aria-label="Guide-Titel" @input="dirty=true"><div><span class="badge">{{dirty?'Ungespeichert':label(selected.status)}}</span><button class="primary" :disabled="busy||!dirty||!allowed('guide.edit')" @click="saveGuide"><Save :size="17"/> {{busy?'Speichert …':'Entwurf speichern'}}</button></div></div><div class="publication-strip"><span><strong>{{publicationLabel(selected)}}</strong><small>{{selected.frontmatter.reviewRequest&&publicationLabel(selected)!=='Online · aktueller Stand'?'Freigabe für diesen Entwurf angefragt':'Gespeicherter Entwurf · Veröffentlichung ist eine eigene Aktion'}}</small></span><button class="secondary" :disabled="dirty||busy" @click="review(chosen)">Vorschau & Veröffentlichung</button><button v-if="allowed('guide.edit')" class="quiet" :disabled="dirty||busy||!!selected.frontmatter.reviewRequest" @click="command({op:'guide.submit',guideId:chosen})">Zur Freigabe einreichen</button></div><div class="editor-grid"><section class="editor-panel"><div class="toolbar"><button :class="{active:!sourceMode}" @click="sourceMode&&switchMode()">Visuell</button><button :class="{active:sourceMode}" @click="!sourceMode&&switchMode()">Markdown</button><span class="toolbar-divider"></span><fieldset v-if="!sourceMode" class="editor-tools" :disabled="!allowed('guide.edit')"><button title="Überschrift" aria-label="Überschrift einfügen" @click="editor.chain().focus().toggleHeading({level:2}).run()"><Heading2 :size="18"/></button><button title="Fett" aria-label="Fett" @click="editor.chain().focus().toggleBold().run()"><Bold :size="18"/></button><button title="Kursiv" aria-label="Kursiv" @click="editor.chain().focus().toggleItalic().run()"><Italic :size="18"/></button><button title="Link" aria-label="Link einfügen" @click="showDialog('link')"><Link :size="18"/></button><button @click="editor.chain().focus().insertTable({rows:3,cols:3,withHeaderRow:true}).run()"><Table :size="17"/> Tabelle</button><button @click="showDialog('box')"><Info :size="17"/> Box</button><button @click="showDialog('screenshot')"><Image :size="17"/> Bildplatzhalter</button></fieldset></div><textarea v-if="sourceMode" v-model="source" :readonly="!allowed('guide.edit')" class="source-editor" aria-label="Markdown-Inhalt" @input="dirty=true"></textarea><EditorContent v-else :editor="editor"/><div class="editor-foot"><span>{{selected.review==='pending'?'Inhalte noch nicht fachlich geprüft':label(selected.review)}} · {{dirty?'Ungespeicherte Änderungen':'Gespeicherter Stand'}}</span><button v-if="dirty" class="text-button" @click="resetEditor">Änderungen verwerfen</button></div></section><aside class="guide-context"><h2>Am Guide arbeiten</h2><p class="muted">Markiere Text im visuellen Editor und füge einen Kommentar hinzu.</p><button class="secondary full" :disabled="sourceMode||dirty||!allowed('comment.write')" @click="showDialog('comment')"><MessageSquare :size="17"/> Text kommentieren</button><button class="quiet full" :disabled="dirty||!allowed('task.write')" @click="showDialog('task')"><Plus :size="16"/> Aufgabe hinzufügen</button><details class="comment-group"><summary>Offene Kommentare ({{bundle?.comments.filter(x=>x.status!=='done').length||0}})</summary><div v-for="c in bundle?.comments.filter(x=>x.status!=='done')" class="comment-preview"><blockquote>{{c.anchor.quote}}</blockquote><p>{{c.body}}</p><div class="inline-actions"><button :disabled="!allowed('comment.write')" class="text-button" @click="showDialog('reply',{id:c.id})">Antworten</button><button :disabled="!allowed('comment.moderate')" class="text-button" @click="command({op:'comment.status',id:c.id,status:'done'})">Erledigen</button></div></div></details><div class="context-section"><h3>Guide verwalten</h3><button class="quiet full" :disabled="dirty||!allowed('guide.organize')" @click="showDialog('move')"><MoveRight :size="16"/> Datei umbenennen</button><button class="quiet full" :disabled="dirty||!allowed('guide.archive')" @click="command({op:'guide.archive',guideId:chosen,archived:selected.lifecycle!=='archived'})"><Archive :size="16"/> {{selected.lifecycle==='archived'?'Archivierung aufheben':'Archivieren'}}</button><button class="quiet full" :disabled="dirty" @click="setPage('versions')"><History :size="16"/> Versionen ansehen</button></div><p class="boundary">Speichern erzeugt einen Entwurfscommit. Es veröffentlicht diesen Guide nicht.</p></aside></div></template>
     </section>
     <section v-if="page==='review'"><div class="page-heading"><div><h1>Freigaben</h1><p>Eingereichte Entwürfe öffnen, prüfen und als Admin veröffentlichen.</p></div></div><ContentLibrary :state="state" review-only @open="openGuide"/></section>
     <section v-if="page==='site'&&state.site"><SiteSettings :site="state.site" :busy="busy" :editable="allowed('site.edit')" :assets="allAssets" :image-source="imageSource" @dirty="siteDirty=$event" @save="command({op:'site.save',site:$event})" @upload="uploadSite" @review="review('site')"/></section>
     <section v-if="page==='release'"><ReleaseReview :key="releaseTarget" :guide="state.guides.find(g=>g.id===releaseTarget)" :site="state.site" :state="state" :can-publish="allowed('content.publish')" :busy="busy" :image-source="imageSource" @back="page=releaseTarget==='site'?'site':'guides'" @publish="publish"/></section>
     <section v-if="page==='users'&&allowed('user.manage')"><div class="page-heading"><div><h1>Benutzer & Rechte</h1><p>GitHub-Konten gezielt für die Academy freischalten.</p></div><button class="primary" @click="showDialog('user',{role:'commentator',subject:'github:',revision:0})">Zugang hinzufügen</button></div><p class="muted">Neue Anmeldungen erhalten keinen Studiozugriff. Discord und E-Mail-Einladungen sind noch nicht eingerichtet. Der Inhaberzugang bleibt erhalten.</p><div class="library-list"><div v-for="u in users" class="user-row"><span><strong>{{u.subject}}</strong><small>Revision {{u.revision}}</small></span><span>{{u.grant_json.role}} · {{u.grant_json.disabled?'Gesperrt':'Aktiv'}}</span><button class="secondary" @click="showDialog('user',{subject:u.subject,role:u.grant_json.role,disabled:u.grant_json.disabled,revision:u.revision})">Rechte bearbeiten</button></div><p v-if="!users.length">Noch keine zusätzlichen Konten freigeschaltet.</p></div></section>
     <section v-if="['screenshots','comments','tasks'].includes(page)">
      <div class="page-heading"><div><h1>{{nav.find(n=>n.id===page).title}}</h1><p>{{page==='screenshots'?'Was noch fehlt und wo es hingehört.':page==='comments'?'Fragen und Korrekturen direkt an der passenden Stelle.':'Offene Prüfungen und die nächsten Schritte.'}}</p></div></div>
      <div class="list-tools"><label class="search-field"><Search :size="18"/><input v-model="query" aria-label="Einträge suchen" placeholder="Einträge suchen"></label><label class="check-label"><input type="checkbox" v-model="includeDone"> Erledigte anzeigen</label></div>
      <div v-if="page==='screenshots'" class="detailed-list"><article v-for="item in screenshots" :key="item.id" :class="{'drop-active':dragTarget===item.id}" @dragover.prevent="!busy&&(dragTarget=item.id)" @dragleave="!$event.currentTarget.contains($event.relatedTarget)&&(dragTarget=null)" @drop="dropImage($event,item)"><div class="image-missing"><img v-if="item.assetId" :src="imageSource('/'+allAssets.find(a=>a.id===item.assetId)?.path.slice('docs/public/'.length))" :alt="allAssets.find(a=>a.id===item.assetId)?.alt"><Image v-else :size="30"/></div><div class="item-copy"><div><span class="badge warning">{{label(item.status)}}</span><small>{{guideTitle(item.guideId)}}</small></div><h2>{{item.title}}</h2><p>{{item.description}}</p><p class="drop-hint">Bild hierher ziehen oder „Bild hochladen“ wählen.</p><small>{{statusForAnchor(item)}}</small></div><div class="row-actions"><button class="secondary" :disabled="busy||!allowed('image.write')" @click="showDialog('upload',{id:item.id,alt:item.title})"><Upload :size="16"/> Bild hochladen</button><button v-if="allAssets.length" :disabled="!allowed('image.write')" class="text-button" @click="showDialog('reuse',{id:item.id,assetId:allAssets[0].id})">Vorhandenes Bild</button><button class="text-button" @click="jump(item)">Zur Stelle <ArrowUpRight :size="16"/></button><button :disabled="!allowed('image.write')" class="text-button" @click="command({op:'screenshot.archive',id:item.id})">Archivieren</button></div></article><p v-if="!screenshots.length" class="empty">Keine passenden Bildaufgaben.</p></div>
      <div v-if="page==='comments'" class="detailed-list"><article v-for="item in comments" :key="item.id"><MessageSquare :size="22"/><div class="item-copy"><small>{{guideTitle(item.guideId)}} · {{statusForAnchor(item)}}</small><blockquote>{{item.anchor.quote}}</blockquote><p>{{item.body}}</p><div v-for="r in item.replies" class="reply"><small>Antwort</small><p>{{r.body}}</p></div></div><div class="row-actions"><select :disabled="!allowed('comment.moderate')" :value="item.status" aria-label="Kommentarstatus" @change="command({op:'comment.status',id:item.id,status:$event.target.value})"><option value="open">Offen</option><option value="in-progress">In Bearbeitung</option><option value="done">Erledigt</option></select><button :disabled="!allowed('comment.write')" class="text-button" @click="showDialog('reply',{id:item.id})">Antworten</button><button class="text-button" @click="jump(item)">Zur Stelle <ArrowUpRight :size="16"/></button></div></article><div v-if="!comments.length" class="empty"><MessageSquare :size="30"/><h2>Noch keine Kommentare.</h2><p>Öffne einen Guide, markiere eine Textstelle und wähle „Text kommentieren“.</p><button class="secondary" @click="openGuide('guide:pets')">Pets-Guide öffnen</button></div></div>
      <div v-if="page==='tasks'" class="detailed-list"><article v-for="item in tasks" :key="item.id"><ListChecks :size="23"/><div class="item-copy"><small>{{guideTitle(item.guideId)}}</small><h2>{{item.title}}</h2><blockquote v-if="item.anchor">{{item.anchor.quote}}</blockquote></div><div class="row-actions"><select :disabled="!allowed('task.write')" :value="item.status" aria-label="Aufgabenstatus" @change="command({op:'task.status',id:item.id,status:$event.target.value})"><option value="open">Offen</option><option value="in-progress">In Bearbeitung</option><option value="done">Erledigt</option></select><button v-if="item.anchor" class="text-button" @click="jump(item)">Zur Stelle <ArrowUpRight :size="16"/></button></div></article><p v-if="!tasks.length" class="empty">Keine offenen Aufgaben in dieser Auswahl.</p></div>
     </section>
     <section v-if="page==='data'"><div class="page-heading"><div><h1>Spieldaten</h1><p>Spielgrenzen und Academy-Empfehlungen bleiben getrennt.</p></div><button class="primary" @click="showDialog('game')"><Plus :size="17"/> Wert hinzufügen</button></div><div class="list-tools"><label class="search-field"><Search :size="17"/><input v-model="query" aria-label="Spieldaten filtern" placeholder="Brett, Effekt oder Spielmodus suchen"></label></div><div v-if="!state.snapshot.gameValues.length" class="empty data-empty"><Database :size="34"/><h2>Erst prüfen, dann übernehmen.</h2><p>Hier pflegst du Spielwerte einmal, damit mehrere Guide-Tabellen dieselben Angaben verwenden können. Zum Beispiel: Brett, Slot und Min-/Max-Wert. Empfehlungen wie „Behalten ab“ stehen getrennt davon. Für normalen Guide-Text brauchst du diesen Bereich nicht. Die Werte aus dem Pets-Entwurf sind noch ungeprüft und deshalb noch nicht übernommen.</p></div><div v-else class="table-scroll"><table><thead><tr><th>Brett / Slot</th><th>Effekt</th><th>Min.</th><th>Max.</th><th>Behalten ab</th><th>Prüfung</th><th></th></tr></thead><tbody><tr v-for="v in state.snapshot.gameValues.filter(v=>matches(v.board+' '+v.effect+' '+v.mode))"><td>{{v.board}} · {{v.slot}}<small>{{v.mode.toUpperCase()}} / {{v.role}}</small></td><td>{{v.effect}}</td><td>{{v.min??'offen'}}</td><td>{{v.max??'offen'}}</td><td>{{v.recommendation?.value??'keine Empfehlung'}}</td><td>{{label(v.verification.status)}}</td><td><button class="text-button" @click="showDialog('game',{...v,classes:v.classIds.join(', '),threshold:v.recommendation?.value??null,region:v.verification.region,patch:v.verification.patch,sourceId:v.verification.sourceIds[0]||''})">Bearbeiten</button></td></tr></tbody></table></div></section>
     <section v-if="page==='versions'"><div class="page-heading"><div><h1>Versionen</h1><p>Änderungen vergleichen und als neuen Entwurf wiederherstellen.</p></div><select v-model="chosen" aria-label="Guide für Versionsverlauf"><option v-for="g in state.guides" :value="g.id">{{g.title}}</option></select></div><p><a href="https://github.com/voidborn-legion/voidborn-legion.github.io/actions" target="_blank" rel="noopener">Veröffentlichungs-Builds bei GitHub ansehen ↗</a></p><div class="version-layout"><div><article v-for="v in selected?.versions" class="version-row"><History :size="18"/><div><strong>{{v.message}}</strong><small>{{new Date(v.time*1000).toLocaleString('de-DE')}} · {{v.sha.slice(0,7)}}</small><div class="inline-actions"><button class="text-button" @click="compare(v.sha)">Vergleichen</button><button class="text-button" :disabled="busy||!allowed('version.restore')" @click="command({op:'guide.restore',guideId:chosen,version:v.sha})"><Undo2 :size="14"/> Wiederherstellen</button></div></div></article></div><pre v-if="diff" class="diff-view">{{diff}}</pre><div v-else class="empty"><FileText :size="30"/><p>Wähle eine Version zum Vergleich mit dem aktuellen Stand.</p></div></div></section>
    </template>
   </div>
  </main>
  <div v-if="dialog" class="dialog-overlay" @click.self="closeDialog"><section class="dialog" role="dialog" aria-modal="true" :aria-labelledby="'dialog-title'"><div class="dialog-title"><h2 id="dialog-title">{{({user:'Benutzerrechte',comment:'Text kommentieren',reply:'Antwort schreiben',task:'Aufgabe hinzufügen',screenshot:'Bildplatzhalter hinzufügen',create:'Neuen Guide erstellen',move:'Guide-Datei umbenennen',upload:'Bild zuordnen',box:'Box einfügen',link:'Link einfügen',reuse:'Vorhandenes Bild verwenden',game:'Spielwert bearbeiten'})[dialog]}}</h2><button aria-label="Dialog schließen" @click="closeDialog"><X :size="21"/></button></div><form @submit.prevent="dialog==='user'?saveUser():submitDialog()"><p v-if="['comment','reply','task'].includes(dialog)" class="muted">Dieser Arbeitsstand gehört zum öffentlichen Repository. Bitte keine privaten Angaben eintragen.</p><p v-if="error" role="alert" class="alert error">{{error}}</p>
   <template v-if="dialog==='user'"><label>GitHub-Konto-ID<input v-model="form.subject" required pattern="github:[0-9]+" placeholder="github:123456"><small>Die numerische GitHub-ID des Kollegen, kein Anzeigename.</small></label><label>Rolle<select v-model="form.role"><option value="player">Kein Studiozugriff</option><option value="reader">Entwürfe lesen</option><option value="commentator">Lesen & kommentieren</option><option value="author">Beiträge schreiben & bearbeiten</option><option value="editor">Redaktion, Medien & Website bearbeiten</option><option value="administrator">Admin einschließlich Veröffentlichung & Benutzerrechten</option></select></label><label class="check-label"><input v-model="form.disabled" type="checkbox"> Zugang sperren</label></template>
   <p v-if="dialog==='screenshot'" class="muted">Der Platzhalter wird an deiner Schreibposition eingefügt. Dein aktueller Text wird dabei als Entwurf mitgespeichert.</p><p v-if="dialog==='upload'" class="muted">Das Bild wird am Platzhalter eingesetzt. Guide und Metadaten werden gemeinsam als Entwurf gespeichert.</p>
   <label v-if="['comment','task'].includes(dialog)">Textstelle<textarea v-model="form.quote" :required="dialog!=='task'" placeholder="Text im Guide markieren oder einen eindeutigen Auszug eingeben"></textarea></label>
   <label v-if="['task','screenshot','create','box'].includes(dialog)">Titel<input v-model="form.title" required autofocus></label>
   <label v-if="['create','move'].includes(dialog)">Dateiname<input v-model="form.slug" required placeholder="zum-beispiel-neuer-dungeon" pattern="[a-z0-9][a-z0-9-]{1,60}"><small>Kleinbuchstaben und Bindestriche. Die Guide-ID bleibt beim Umbenennen erhalten.</small></label>
   <label v-if="dialog==='create'">Thema<select v-model="form.categoryId"><option value="">Noch nicht zugeordnet</option><option v-for="c in state.snapshot.catalog.categories" :value="c.id">{{state.categories.find(x=>x.slug===c.slug)?.title||c.slug}}</option></select></label>
   <label v-if="dialog==='box'">Box-Art<select v-model="form.kind"><option value="info">Infobox</option><option value="details">Klappbox</option><option value="tip">Tipp</option><option value="warning">Warnung</option><option value="danger">Wichtige Warnung</option></select></label>
   <label v-if="['comment','reply','box','link'].includes(dialog)">{{dialog==='link'?'Zieladresse':'Text'}}<textarea v-model="form.body" required autofocus></textarea></label>
   <label v-if="dialog==='reuse'">Bild auswählen<select v-model="form.assetId" required><option v-for="a in allAssets" :value="a.id">{{a.alt}}</option></select></label><label v-if="dialog==='screenshot'">Welches Bild fehlt?<textarea v-model="form.description" required></textarea></label>
   <template v-if="dialog==='upload'"><label>Bilddatei<span v-if="form.file" class="chosen-file">{{form.file.name}} · {{Math.ceil(form.file.size/1024)}} KB</span><input type="file" accept="image/png,image/jpeg,image/webp" :required="!form.file" @change="form.file=$event.target.files[0]||form.file"><small>PNG, JPEG oder WebP · maximal 2 MB</small></label><label>Alternativtext<input v-model="form.alt" required></label><label>Bildunterschrift<input v-model="form.caption"></label></template>
   <template v-if="dialog==='game'"><div class="form-pair"><label>Brett<select v-model="form.board"><option>Cognia</option><option>Fera</option><option>Natura</option><option>Varia</option><option>Specia</option></select></label><label>Slot<input type="number" min="1" max="9" v-model="form.slot" required></label></div><label>Effekt<input v-model="form.effect" required></label><div class="form-pair"><label>Rolle<select v-model="form.role"><option value="dps">Schaden</option><option value="tank">Tank</option><option value="healer">Heiler</option><option value="support">Support</option></select></label><label>Klassen (optional)<input v-model="form.classes" placeholder="zum Beispiel Templer, Kleriker"></label></div><div class="form-pair"><label>Modus<select v-model="form.mode"><option value="pve">PvE</option><option value="pvp">PvP</option></select></label><label>Einheit<select v-model="form.unit"><option value="percent">Prozent</option><option value="points">Punkte</option></select></label></div><div class="form-pair"><label>Minimum<input v-model="form.min" type="number" step="any" placeholder="unbekannt"></label><label>Maximum<input v-model="form.max" type="number" step="any" placeholder="unbekannt"></label></div><label>Academy-Stoppschwelle (optional)<input v-model="form.threshold" type="number" step="any"></label><label>Quelle<select v-model="form.sourceId"><option value="">Noch nicht belegt</option><option v-for="s in state.snapshot.sources" :value="s.id">{{s.title}}</option></select></label><div class="form-pair"><label>Region<input v-model="form.region" required></label><label>Patchstand<input v-model="form.patch" placeholder="noch offen"></label></div><p class="muted">Der Eintrag wird als unbestätigt gespeichert. Eine Stoppschwelle ist eine Empfehlung, keine offizielle Spielgrenze.</p></template>
   <div class="dialog-actions"><button type="button" class="quiet" @click="closeDialog">Abbrechen</button><button class="primary" :disabled="busy">{{busy?'Speichert …':dialog==='box'||dialog==='link'?'Einfügen':dialog==='user'?'Rechte speichern':'Als Entwurf speichern'}}</button></div>
  </form></section></div>
 </div>
</template>
